L29_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_CHALLENGE_ACT2_1_5"
L30_1 = "<color=#ff2626>[BOSS STAGE]：感應到高度危險的個體！</color>\n潛伏在深海裡的侵蝕體開始登陸。\n隨著時間的推移，新的侵蝕體聽到聲音將加入戰鬥。"
L28_1[1] = L29_1
L28_1[2] = L30_1
