L24_1 = "SI_PF_TUTORIAL_TEXUTRE_OPERATOR_COMPOSE_1_DESC"
L25_1 = "可將領航員作為材料<COLOR=#FFBC00>升級技術</COLOR>或<COLOR=#FFBC00>變更為其他技術</COLOR>。"
L23_1[1] = L24_1
L23_1[2] = L25_1
L24_1 = {}
L25_1 = "SI_PF_TUTORIAL_TEXUTRE_OPERATOR_COMPOSE_2_DESC"
L26_1 = "可將<COLOR=#FFBC00>擁有相同技術的領航員</COLOR>作為材料，提升技術等級。\n作為材料的領航員等級越高，成功機率就越高，即使失敗，也會保持原有技術。\n用作材料的領航員在合成時不論成功與否都會消耗。"
L24_1[1] = L25_1
L24_1[2] = L26_1
L25_1 = {}
L26_1 = "SI_PF_TUTORIAL_TEXUTRE_OPERATOR_COMPOSE_3_DESC"
L27_1 = "可將<COLOR=#FFBC00>擁有不同輔助技術的領航員</COLOR>作為材料，變更所需的輔助技術。\n只能使用與欲變更輔助技術的領航員<COLOR=#FFBC00>相同等級或者更高等級的領航員</COLOR>作為材料。\n將<COLOR=#FFBC00>輔助技術變更按鈕切換為ON</COLOR>時才可以成功變更輔助技術。\n成功變更輔助技術時，<COLOR=#FFBC00>原有的輔助技術等級會初始化為1級</COLOR>。"
L25_1[1] = L26_1
L25_1[2] = L27_1
