L35_1[1] = L36_1
L35_1[2] = L37_1
L36_1 = {}
L37_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EP5_ACT5_INTERLUDE_5"
L38_1 = "被權力糾纏的命運，喚醒了沉睡著的人們"
L36_1[1] = L37_1
L36_1[2] = L38_1
L37_1 = {}
L38_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EP5_ACT5_INTERLUDE_6"
L39_1 = "即使命運擁有聲音，它也會為了你保持沉默。\n真摯的感情無需訴說，它自然就會湧現。"
L37_1[1] = L38_1
L37_1[2] = L39_1
L38_1 = {}
L39_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_ADMIN_1_1"
L40_1 = "梅茲戰隊長，我馬上會提供支援。\n一定要撐住，如果防線現在被破壞，現世就會毀滅。"
L38_1[1] = L39_1
L38_1[2] = L40_1
L39_1 = {}
L40_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_ADMIN_1_1_CM"
L41_1 = "疲勞和貧窮會使演奏更加強烈。  <color=#ff3636>必需解除集中在雅蕾克絲身上的攻擊速度增益。</color> <color=#ff3636>※注意※相比其他困難關卡的難度要更高。</color>"
L39_1[1] = L40_1
L39_1[2] = L41_1
L40_1 = {}
L41_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_ADMIN_1_2"
L42_1 = "作戰記錄錄音，這次作戰可能會很危險。\n但為了那些信任我的人們，我必須表現得更堅強。"
L40_1[1] = L41_1
L40_1[2] = L42_1
L41_1 = {}
L42_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_ADMIN_1_2_CM"
L43_1 = "統治者必需顯露威嚴。  <color=#ff3636>羅莎莉亞會造成與當前體力值成比例的強大傷害，因此屏障的使用極為重要。</color> <color=#ff3636>※注意※相比其他困難關卡的難度要更高。</color>"
L41_1[1] = L42_1
L41_1[2] = L43_1
L42_1 = {}
L43_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_ADMIN_1_3"
L44_1 = "自悠久的歷史之初起，她便是最兇惡的暴君、征服者、也是毀天滅地者。"
L42_1[1] = L43_1
L42_1[2] = L44_1
L43_1 = {}
