L7_1[2] = L9_1
L8_1 = {}
L9_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_ADMIN_2_EPILOGUE"
L10_1 = "那個靈魂在慘白的戰場徘徊著。"
L8_1[1] = L9_1
L8_1[2] = L10_1
L9_1 = {}
L10_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_ADMIN_2_INTERLUDE_1"
L11_1 = "二重身會拼命地試圖吸收自己的本體。\n但凡事都有例外。"
L9_1[1] = L10_1
L9_1[2] = L11_1
L10_1 = {}
L11_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_ADMIN_2_INTERLUDE_2"
L12_1 = "異界是珍藏著一個世界最後瞬間的空間。 \n而本應消逝的存在也被妄念永遠困在了那個地方。"
L10_1[1] = L11_1
L10_1[2] = L12_1
L11_1 = {}
L12_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_ADMIN_2_INTERLUDE_3"
L13_1 = "姐妹們試圖重新組合破碎的世界。\n但她們不該那麼做，她們本應該讓世界維持現狀。\n因為這樣做反而蒙住了她們的雙眼，讓她們執迷於無法實現的夢想。"
L11_1[1] = L12_1
L11_1[2] = L13_1
L12_1 = {}
L13_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_ADMIN_2_INTERLUDE_4"
L14_1 = "侵蝕體互相殘殺的場景並不鮮見。"
L12_1[1] = L13_1
L12_1[2] = L14_1
L13_1 = {}
L14_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_BARCODE_1_1"
L15_1 = "孩子們在炫耀的話，請停止手中的工作，仔細聽聽看吧。"
L13_1[1] = L14_1
L13_1[2] = L15_1
L14_1 = {}
L15_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_BARCODE_1_2"
L16_1 = "孩子們很不會忘記過去不好的記憶。"
L14_1[1] = L15_1
L14_1[2] = L16_1
L15_1 = {}
L16_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_BARCODE_1_3"
L17_1 = "比起一個人一起更好。"
L15_1[1] = L16_1
L15_1[2] = L17_1
L16_1 = {}
L17_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_BARCODE_1_EPILOGUE"
L18_1 = "我的妹妹哪有這麼多！"
L16_1[1] = L17_1
L16_1[2] = L18_1
L17_1 = {}
L18_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_BARCODE_1_INTERLUDE_1"
L19_1 = "可能會和西格瑪成為好朋友。"
L17_1[1] = L18_1
L17_1[2] = L19_1
L18_1 = {}
L19_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_BARCODE_1_PROLOGUE"
L20_1 = "特遣勢力需要處理很多危險的裝備。\n管理局爲應對安全事故將定期進行安全教育。"
L18_1[1] = L19_1
L18_1[2] = L20_1
L19_1 = {}
L20_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_CROSSROAD_R_1_1"
L21_1 = "警告，秘密研究設施出現入侵者。\n設施內所有戰力請立刻應對。"
L19_1[1] = L20_1
L19_1[2] = L21_1
L20_1 = {}
L21_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_CROSSROAD_R_1_1_HM"
L22_1 = "不是過去，也不是未來，而是從法則的另一邊穿越而來的異邦人。"
L20_1[1] = L21_1
L20_1[2] = L22_1
L21_1 = {}
L22_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_CROSSROAD_R_1_2"
L23_1 = "我們常常會陷入這樣的錯覺，以為用消除法得到的辦法一定是更好的。一句“別無他法”往往會成為一個很好的藉口。"
L21_1[1] = L22_1
L21_1[2] = L23_1
L22_1 = {}
L23_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_CROSSROAD_R_1_PROLOGUE"
L24_1 = "我不怕這廣闊的世界就只有我們。 而是害怕只剩下我們。"
L22_1[1] = L23_1
L22_1[2] = L24_1
