L5_1 = {}
L6_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_FOOLSDAY_1_5"
L7_1 = "想容納更多的員工就必須擴大辦公空間。\n如果能和員工們同心同體的話，那就另當別論了。"
L5_1[1] = L6_1
L5_1[2] = L7_1
L6_1 = {}
