L6_1[1] = L7_1
L6_1[2] = L8_1
L7_1 = {}
L8_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_FOOLSDAY_1_EPILOGUE"
L9_1 = "\"開始反覆戰鬥。\""
L7_1[1] = L8_1
L7_1[2] = L9_1
L8_1 = {}
L9_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_FOOLSDAY_1_PROLOGUE"
L10_1 = "為了買肉而來逛菜市場的米娜，遭遇了不幸的事故。"
L8_1[1] = L9_1
L8_1[2] = L10_1
L9_1 = {}
L10_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_MAID_1_1"
L11_1 = "特遣勢力因為隨時待命的原因，很容易忽略日常生活。\n因此出現了很多為他們服務的公司。\n\n<color=#ffd34c>雜亂的環境會影響工作效率，通過清掃改善氛圍吧。</color>"
L9_1[1] = L10_1
L9_1[2] = L11_1
L10_1 = {}
L11_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_MAID_1_3"
L12_1 = "經歷PTSD的傭兵，會因小小的契機而想起使自己受到心理創傷的痛苦瞬間。"
L10_1[1] = L11_1
L10_1[2] = L12_1
L11_1 = {}
L12_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_MAID_1_3_HM"
L13_1 = "但是，從來不和其他女僕來往。\n因為有其他要做的事情。"
L11_1[1] = L12_1
L11_1[2] = L13_1
L12_1 = {}
L13_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_MAID_1_4"
L14_1 = "尋花香而來的不僅僅只有蝴蝶。"
L12_1[1] = L13_1
L12_1[2] = L14_1
L13_1 = {}
L14_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_MAID_1_INTERLUDE_1"
L15_1 = "僅靠書上的知識是無法滿足的。\n需要通過經驗和觀察，來消除對知識的好奇心。\n哪怕有時會違背社會的傳統觀念。"
L13_1[1] = L14_1
L13_1[2] = L15_1
L14_1 = {}
L15_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_MAID_1_INTERLUDE_2"
L16_1 = "既然起了疑心，就只能確認一下了。"
L14_1[1] = L15_1
L14_1[2] = L16_1
L15_1 = {}
L16_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_MAID_1_INTERLUDE_3"
L17_1 = "這個地方不太適合同居。"
L15_1[1] = L16_1
L15_1[2] = L17_1
L16_1 = {}
L17_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_MAID_1_PROLOGUE"
L18_1 = "那些快艇嗎？\n都是來這附近遊玩的人們所有的。\n像我們這樣的，只要有個小漁船就已經謝天謝地了。"
L16_1[1] = L17_1
L16_1[2] = L18_1
L17_1 = {}
L18_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_MAID_2_1"
L19_1 = "在黑色水面泛起漣漪的白色泡沫。\n在藍色的寂靜中飄蕩的紅色記憶。"
L17_1[1] = L18_1
L17_1[2] = L19_1
L18_1 = {}
L19_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_MAID_2_1_HM"
L20_1 = "備受尊敬的女僕長，把即將被拋棄的小孩子\n收為直屬手下的事情曾一度在曼森成為焦點。"
L18_1[1] = L19_1
L18_1[2] = L20_1
L19_1 = {}
L20_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_MAID_2_2"
L21_1 = "G1是計畫城市，\n在突變的特遣勢力市場中，經歷了各種大大小小的風波。\n而其中幾個趁著混亂站穩了腳跟，並集中於經濟活動。"
L19_1[1] = L20_1
L19_1[2] = L21_1
L20_1 = {}
L21_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_MAID_2_3"
L22_1 = "組織的隱語會提高歸屬感，還可以誤導他人。"
L20_1[1] = L21_1
L20_1[2] = L22_1
L21_1 = {}
L22_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_MAID_2_4"
L23_1 = "開在曼森的花朵無法逃過凋謝或被人折掉的短暫命運。\n一直到現在。"
L21_1[1] = L22_1
L21_1[2] = L23_1
