L1_1 = {}
L2_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_ORCA_3_3"
L3_1 = "感情的深淺不與時間成正比。\n\n有些人一瞬間的行為能成為另一個人一生的支柱。"
L1_1[1] = L2_1
L1_1[2] = L3_1
L2_1 = {}
L3_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_POLICE_1_1"
L4_1 = "暴力犯罪根據犯罪主體大致分為兩種類型。\n如果罪犯是武裝的普通人，倒還算萬幸。"
L2_1[1] = L3_1
L2_1[2] = L4_1
L3_1 = {}
L4_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_POLICE_1_2"
L5_1 = "國家警察長久以來一直面臨著人才不足的問題。\n因為僅憑普通人是無法應對制裁者犯罪的。"
L3_1[1] = L4_1
L3_1[2] = L5_1
L4_1 = {}
L5_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_POLICE_1_3"
L6_1 = "維持秩序必需依靠力量。\n但力量往往會追隨金錢。\n警察的影響力變得比傭兵弱小已經是很久之前的事情了。"
L4_1[1] = L5_1
L4_1[2] = L6_1
L5_1 = {}
L6_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_POLICE_2_1"
L7_1 = "關於聖水的傳聞被過度美化了。\n從沒有人提及服用者的最後下場。"
L5_1[1] = L6_1
L5_1[2] = L7_1
L6_1 = {}
L7_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_POLICE_2_2"
L8_1 = "世界上沒有所謂至善。\n越是追求那種東西，只會變得更加不幸。"
L6_1[1] = L7_1
L6_1[2] = L8_1
L7_1 = {}
L8_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_POLICE_2_3"
L9_1 = "異端堅信為了前往樂土必需要有犧牲。 \n就算跟他們說樂土位於火海之中，他們也會深信不疑。"
L7_1[1] = L8_1
L7_1[2] = L9_1
L8_1 = {}
L9_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_POLICE_3_1"
L10_1 = "正義並非審判。\n它只是為了拯救人命而不斷地做出選擇而已。"
L8_1[1] = L9_1
L8_1[2] = L10_1
L9_1 = {}
L10_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_POLICE_3_2"
L11_1 = "警察保護法律不被犯罪所玷污。\n即使世界再怎麼變，這個事實也不會改變。"
L9_1[1] = L10_1
L9_1[2] = L11_1
L10_1 = {}
L11_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_POLICE_3_3"
L12_1 = "結果會告知一切。\n達成的成果、犯下的過錯、我錯過的一切……\n只是到了那時候，一切都將變得無法挽回。"
L10_1[1] = L11_1
L10_1[2] = L12_1
L11_1 = {}
L12_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_POLICE_3_4"
L13_1 = "趁還來得及，我想挽回這一切。\n至少那個孩子還有家人，以及度過平凡的人生的機會。"
L11_1[1] = L12_1
L11_1[2] = L13_1
L12_1 = {}
L13_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_POLICE_EPILOGUE"
L14_1 = "不用太擔心，刑警系列每次都會以懲惡揚善告終。"
L12_1[1] = L13_1
L12_1[2] = L14_1
L13_1 = {}
L14_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_POLICE_INTERLUDE_1"
L15_1 = "沒有什麼詞比“信任”更符合過猶不及這一成語。"
L13_1[1] = L14_1
L13_1[2] = L15_1
L14_1 = {}
L15_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_SOF_1_1"
L16_1 = "代表這個稱呼聽起來很厲害。但員工只有一人的話，就顯得很沒面子了。\n\n在外面飽受貸款的苦惱，在內部又受到部下虐待的約翰就是這種情況。"
L14_1[1] = L15_1
L14_1[2] = L16_1
L15_1 = {}
L16_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_SOF_1_2"
L17_1 = "梅森傭兵事務所收到了久違的委託。\n但不是開心到值得打開香檳慶祝的事情。\n\n誰知道身份不明的雇主給的委託金是否會成為撫恤金呢。"
L15_1[1] = L16_1
L15_1[2] = L17_1
L16_1 = {}
L17_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_SOF_2_1"
L18_1 = "沒有錢令人窘迫。\n有時甚至會一隻腳踏進墳墓。"
L16_1[1] = L17_1
L16_1[2] = L18_1
L17_1 = {}
L18_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_SOF_2_2"
L19_1 = "不要輕信陌生人的話。\n錢包空空也不能頭腦空空。"
L17_1[1] = L18_1
L17_1[2] = L19_1
L18_1 = {}
L19_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_SOF_2_3"
L20_1 = "運氣不好甚至會遭到晴天霹靂。"
L18_1[1] = L19_1
L18_1[2] = L20_1
L19_1 = {}
L20_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_SOF_3_1"
L21_1 = "前有制裁者，後有侵蝕體，在這進退兩難的情況下。\n\n剩餘的選擇只有一個。"
L19_1[1] = L20_1
L19_1[2] = L21_1
L20_1 = {}
L21_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_SOF_3_2"
L22_1 = "極端的情況下需要作出極端的選擇。"
L20_1[1] = L21_1
L20_1[2] = L22_1
L21_1 = {}
L22_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_SOF_3_3"
L23_1 = "超速行駛與胡亂行駛會讓你的和他人同時陷入危險。 \n\n除非有制裁者在追殺你。"
L21_1[1] = L22_1
L21_1[2] = L23_1
L22_1 = {}
L23_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_SOF_4_1"
L24_1 = "那個男人並未忘記他的兄弟。\n\n所以只要有空，他都會把紀念兄弟的象徵升上天空。"
L22_1[1] = L23_1
L22_1[2] = L24_1
L23_1 = {}
L24_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_SOF_4_2"
L25_1 = "制裁者是侵蝕戰中的主力。\n\n不僅獨自一人就能抵擋侵蝕體， 看到他們，我軍部隊的士氣也會大大提高。"
L23_1[1] = L24_1
L23_1[2] = L25_1
L24_1 = {}
L25_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_SOF_4_3"
L26_1 = "諷刺的是，越是人生的絆腳石，就越是難纏。"
L24_1[1] = L25_1
L24_1[2] = L26_1
L25_1 = {}
L26_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_SOF_4_4"
L27_1 = "事件完成後，約翰像往常一樣回到和平的事務所。\n\n但，又有新的事件在等著他。"
L25_1[1] = L26_1
L25_1[2] = L27_1
L26_1 = {}
L27_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_SOF_4_5"
L28_1 = "一直以來，傭兵的第一項原則就是'活下來再說’。"
L26_1[1] = L27_1
L26_1[2] = L28_1
L27_1 = {}
