L14_1 = {}
L15_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_SPORTS_1_1"
L16_1 = "制裁者學院歡迎所有未成年制裁者入學。\n\n<color=#ff3636>抓住天上的金色啄木鳥時可獲得出擊資源。</color>\n"
L14_1[1] = L15_1
L14_1[2] = L16_1
L15_1 = {}
L16_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_SPORTS_1_1_CM"
L17_1 = "雖然說只是暫時合作，但也可能會合作無間。\n\n<color=#ff3636>奈爾每次除掉較弱的敵人時都會變得更加狂妄自大。請利用這一點。</color>"
L15_1[1] = L16_1
L15_1[2] = L17_1
L16_1 = {}
L17_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_SPORTS_1_1_HM"
L18_1 = "熱情、憤怒以及過度的自戀。\n全都在燃燒的紅色。\n\n<color=#ff3636>抓住天上的金色啄木鳥時可獲得出擊資源。</color>"
L16_1[1] = L17_1
L16_1[2] = L18_1
L17_1 = {}
L18_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_SPORTS_1_2"
L19_1 = "作為隊伍的主力出戰，背負了比想像中更重的責任。\n\n<color=#ff3636>抓住天上的金色啄木鳥時可獲得出擊資源。</color>"
L17_1[1] = L18_1
L17_1[2] = L19_1
L18_1 = {}
L19_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_SPORTS_1_3"
L20_1 = "在我們的運動會上，通過加油也能拿到分數。\n熱情可以評分，舞蹈不予評分。\n\n<color=#ff3636>抓住天上的金色啄木鳥時可獲得出擊資源。</color>"
L18_1[1] = L19_1
L18_1[2] = L20_1
L19_1 = {}
L20_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_SPORTS_1_4"
L21_1 = "秘密之島上沒有侵蝕體的容身之地。"
L19_1[1] = L20_1
L19_1[2] = L21_1
L20_1 = {}
L21_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_SPORTS_1_5"
L22_1 = "躲避球很危險，尤其是制裁者丟出的球，更是危險至極。\n\n<color=#ff3636>抓住天上的金色啄木鳥時可獲得出擊資源。</color>"
L20_1[1] = L21_1
L20_1[2] = L22_1
L21_1 = {}
L22_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_SPORTS_1_6"
L23_1 = "認真傾聽內心的聲音吧，\n不是用耳朵來聽。"
L21_1[1] = L22_1
L21_1[2] = L23_1
L22_1 = {}
L23_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_SPORTS_1_7"
L24_1 = "不需要頒獎典禮。\n因為冠軍應該已經拿到獎品了。"
L22_1[1] = L23_1
L22_1[2] = L24_1
L23_1 = {}
L24_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_SPORTS_1_INTERLUDE_1"
L25_1 = "學院學生會的職責範圍比其他任何學校的學生會都還多出了許多。"
L23_1[1] = L24_1
L23_1[2] = L25_1
L24_1 = {}
