L24_1 = "SI_SHOP_CASH_ITEM_POPUP_DESC_170041"
L25_1 = "<color=#03A9F4>[購買後立刻獲得]</color>\n- 鑽石x 1,200\n永恆之金x 5,000\n\n<color=#03A9F4>[連續10天獲得]</color>\n- 雇傭契約書x 1"
