L2_1 = {}
L3_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_ESPR2_ACT7_EPILOGUE1"
L4_1 = "學會必須一直待在冰冷的黑暗裡，一邊做著無法實現的夢。"
L2_1[1] = L3_1
