L6_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_ESPR2_ACT6_INTERLUDE1"
L7_1 = "所有的樂器是一體的，因此即便是再微小的差錯，都會像水面上的漣漪般擴散至整個水面，所以必須盡快剷除。"
L5_1[1] = L6_1
