L34_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_NANAHARA2_1_1"
L35_1 = "領地那端是現在只剩下死亡的世界，我們稱之為地獄。以前曾經是我們的祖先和神共同生活的地方。"
L33_1[1] = L34_1
L33_1[2] = L35_1
