L6_1 = "邊框 : 雪花兔子"
L4_1[1] = L5_1
L4_1[2] = L6_1
L5_1 = {}
L6_1 = "SI_UNIT_SKILL_DESC_ADMIN_C_RABBIT_ATTACK_LV1"
L7_1 = "發射雪花箭矢對射中的敵人造成傷害。"
L5_1[1] = L6_1
L5_1[2] = L7_1
L6_1 = {}
L7_1 = "SI_UNIT_SKILL_DESC_ADMIN_C_RABBIT_HYPER_LV1"
L8_1 = "利用夢幻品種的能力產生強烈的雪花箭矢，對射中的敵人與其周圍造成範圍傷害。對超過有效打擊數的敵人不會造成傷害，並賦予射中的敵人[寒氣]3疊加。"
L6_1[1] = L7_1
L6_1[2] = L8_1
L7_1 = {}
L8_1 = "SI_UNIT_SKILL_DESC_ADMIN_C_RABBIT_PASSIVE_LV1"
L9_1 = "不受到攻擊速度增加/減少的影響。賦予遭普通攻擊射中的敵人[寒氣]1疊加。每次出擊僅限1次，體力在40%以下時，會往後方輕跳，再向前方敵人發射多發雪花箭矢造成範圍傷害。賦予遭多發雪花箭矢射中的敵人[寒氣]3疊加。"
L7_1[1] = L8_1
L7_1[2] = L9_1
