L25_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ROOT_CA_HUNTRESS@AB_UI_UNIT_VOICE_NKM_UNIT_ROOT_CA_HUNTRESS_LOBBY_TOUCH_NORMAL_1"
L26_1 = "公司經營狀況不好嗎？我的薪水可以用其他東西支付沒關係。什麼？葡萄嗎？不，不好吧？我是喜歡葡萄沒錯…但這麼用那麼昂貴的東西能代替薪水沒關係嗎？老闆之後不會後悔吧？"
L24_1[1] = L25_1
L24_1[2] = L26_1
L25_1 = {}
L26_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ROOT_CA_HUNTRESS@AB_UI_UNIT_VOICE_NKM_UNIT_ROOT_CA_HUNTRESS_LOBBY_TOUCH_NORMAL_2"
L27_1 = "對聖騎士來說，幫助弱者是我的榮耀。雖然老闆是我的救命恩人，但你比我還弱小，所以我會保護你的！請放心倚靠我吧！"
L25_1[1] = L26_1
L25_1[2] = L27_1
L26_1 = {}
