L7_1 = {}
L8_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_AURA@AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_AURA_LOBBY_CONNECT_LIFETIME"
L9_1 = "哈囉手下，早安喔？"
