L7_1[2] = L9_1
L8_1 = {}
L9_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_AURA@AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_AURA_LOBBY_TOUCH_NORMAL_1"
L10_1 = "要展現出自信的一面才能獲得他人的信任。所以我一直在跟奧蘿師父學習，比如撂下深刻印象的一句話…或是帥氣的出場姿勢之類的。"
L8_1[1] = L9_1
L8_1[2] = L10_1
L9_1 = {}
L10_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_AURA@AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_C_AURA_LOBBY_TOUCH_NORMAL_2"
L11_1 = "我有很多缺點，譬如不會拒絕別人，也很容易受氛圍影響。但正因為如此，和奧蘿師父在一起時，像我這種膽小鬼也能產生勇氣吧？"
L9_1[1] = L10_1
L9_1[2] = L11_1
