L37_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_SA_COMMANDER@AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_SA_COMMANDER_LOBBY_TOUCH_NORMAL_1"
L38_1 = "死亡理當伴隨著安息，我們有義務讓受苦的暗影享受這份權利。但另一方面，也應該尊重他們超越死亡的忠誠。就像我的暗影們，還有你看重的暗影一樣。"
L36_1[1] = L37_1
L36_1[2] = L38_1
L37_1 = {}
L38_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_SA_COMMANDER@AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_SA_COMMANDER_LOBBY_TOUCH_NORMAL_2"
L39_1 = "礙於我的身分地位，檯面上我不得不與你的管理局敵對。但私底下，我無意詆毀或是為難你。相反的，我要幫助你，因為你不能輕易倒下。"
L37_1[1] = L38_1
L37_1[2] = L39_1
L38_1 = {}
L39_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_SA_COMMANDER@AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_SA_COMMANDER_LOBBY_TOUCH_NORMAL_3"
L40_1 = "你是否握過垂死士兵的手？那冰冷的手顫抖地緊抓著你，這樣的景象，經過數日後依舊難以忘懷。這對於讓自己的心振作起來很有效。"
L38_1[1] = L39_1
L38_1[2] = L40_1
L39_1 = {}
L40_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_SA_COMMANDER@AB_UI_UNIT_VOICE_NKM_UNIT_REAPER_SA_COMMANDER_LOBBY_TOUCH_NORMAL_4"
L41_1 = "通常在思考要不要結束一個人的性命時，只需要吸一口氣的時間。而我們現在相視而坐，邊喝著紅茶，就表示…至少今天還不是時候。"
L39_1[1] = L40_1
L39_1[2] = L41_1
L40_1 = {}
