L17_1 = {}
L18_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_BETA_S_REPLICA@AB_UI_UNIT_VOICE_NKM_UNIT_BETA_S_REPLICA_GET_01"
L19_1 = "在曼森綻放的黑色玫瑰向您獻上永遠的忠誠。請下令吧，主人。"
L17_1[1] = L18_1
L17_1[2] = L19_1
L18_1 = {}
L19_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_BETA_S_REPLICA@AB_UI_UNIT_VOICE_NKM_UNIT_BETA_S_REPLICA_LOBBY_CAPTAIN"
L20_1 = "是，我們無論何時、何地，都會守護在主人的身旁。"
L18_1[1] = L19_1
L18_1[2] = L20_1
L19_1 = {}
L20_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_BETA_S_REPLICA@AB_UI_UNIT_VOICE_NKM_UNIT_BETA_S_REPLICA_LOBBY_CONNECT"
L21_1 = "歡迎主人回來，今天有什麼吩咐嗎？"
L19_1[1] = L20_1
L19_1[2] = L21_1
L20_1 = {}
L21_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_BETA_S_REPLICA@AB_UI_UNIT_VOICE_NKM_UNIT_BETA_S_REPLICA_LOBBY_CONNECT_LIFETIME"
L22_1 = "今天也準備了您平時喝的茶。主人，請誇我。"
L20_1[1] = L21_1
L20_1[2] = L22_1
L21_1 = {}
L22_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_BETA_S_REPLICA@AB_UI_UNIT_VOICE_NKM_UNIT_BETA_S_REPLICA_LOBBY_TOUCH_NORMAL_1"
L23_1 = "您是主人的主人…也就是真正的主人。若是如此，那您自然也配得上我們的服務。來吧，主人，請吩咐。"
L21_1[1] = L22_1
L21_1[2] = L23_1
