L12_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ZODIAC_CA_CHARLOTTE@AB_UI_UNIT_VOICE_NKM_UNIT_ZODIAC_CA_CHARLOTTE_LOBBY_CONNECT"
L13_1 = "待命中，一切正常。等候指示中。"
L11_1[1] = L12_1
L11_1[2] = L13_1
L12_1 = {}
L13_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ZODIAC_CA_CHARLOTTE@AB_UI_UNIT_VOICE_NKM_UNIT_ZODIAC_CA_CHARLOTTE_LOBBY_CONNECT_LIFETIME"
L14_1 = "我一直在等你。果然，身邊沒有你總覺得空虛呢。"
