L39_1 = "我一直在等你，管理者。"
L37_1[1] = L38_1
L37_1[2] = L39_1
L38_1 = {}
L39_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_CA_CLOUD@AB_UI_UNIT_VOICE_NKM_UNIT_ADMIN_CA_CLOUD_LOBBY_CONNECT_LIFETIME"
L40_1 = "我在等你……嗯，抱歉。因為嘴巴閒著就吃了點柿餅。"
