L3_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_SS_OMEN_2_INTERLUDE1"
L4_1 = "為了更好的世界，我會用盡我一切力量。\n因為爺爺跟你……一定也會這麼做吧。"
L2_1[1] = L3_1
