L14_1[2] = L16_1
L15_1 = {}
L16_1 = "SI_SKILL_NAME_OPR_DOGABI"
L17_1 = "化凶為吉：大囚獄殺"
L15_1[1] = L16_1
L15_1[2] = L17_1
L16_1 = {}
L17_1 = "SI_SKILL_DESC_OPR_DOGABI"
L18_1 = "在<color=#ffd34c>8秒</color>內，對<color=#ffd34c>BOSS以外的所有敵方單位</color>賦予<color=#ffd34c>技能封印◇</color>狀態。在<color=#ffd34c>16秒</color>內賦予<color=#ffd34c>所有我方單位</color>賦予<color=#ffd34c>技能封印◇</color>狀態和<color=#ffd34c>{stat1}增加{factor1}%、{stat2}增加{value2}%</color>的效果。使<color=#ffd34c>我方護衛和前鋒</color>除了持續時間外的其餘效果數值將以<color=#ffd34c>1/3</color>套用。此效果<color=#ffd34c>無法解除</color>。"
L16_1[1] = L17_1
L16_1[2] = L18_1
L17_1 = {}
L18_1 = "AB_UI_UNIT_VOICE_OPR_DOGABI@AB_UI_UNIT_VOICE_OPR_DOGABI_GET_01"
L19_1 = "我是個不作詩的詩人，也是個不揮劍的劍客。若你執意要使喚這把老骨頭，我也只能在一旁，說些無關緊要的小故事。若你不嫌棄的話。"
