L9_1[2] = L11_1
L10_1 = {}
L11_1 = "SI_EXPLORE_EVENT_MAINDESC_80064_5"
L12_1 = "你來得正好。要我同時對付這些祖先，對我來說也有點吃力。"
L10_1[1] = L11_1
L10_1[2] = L12_1
L11_1 = {}
L12_1 = "SI_EXPLORE_EVENT_MAINDESC_80064_6"
L13_1 = "他們……只是被執念吞噬，失去了自我而已。"
L11_1[1] = L12_1
L11_1[2] = L13_1
L12_1 = {}
L13_1 = "SI_EXPLORE_EVENT_MAINDESC_80064_7"
L14_1 = "我不希望那些逝去的人，還要以這種方式承受痛苦。"
L12_1[1] = L13_1
L12_1[2] = L14_1
L13_1 = {}
L14_1 = "SI_EXPLORE_EVENT_MAINDESC_80064_8"
