L16_1[2] = L18_1
L17_1 = {}
L18_1 = "SI_EXPLORE_EVENT_RESULTDESC1_80064_2"
L19_1 = "就如同那些即便在異界幻象中，為了成為龍而戰鬥的祖先。"
L17_1[1] = L18_1
L17_1[2] = L19_1
