L20_1 = "SI_EXPLORE_EVENT_RESULTDESC1_80064_4"
L21_1 = "如同自遠古開始輪迴、蛇般的命運之繩，造就了現在的我。"
L19_1[1] = L20_1
L19_1[2] = L21_1
L20_1 = {}
L21_1 = "SI_EXPLORE_EVENT_RESULTDESC1_80064_5"
L22_1 = "那條由他們交付於我的命運之繩……希望能為他們帶來安息。"
L20_1[1] = L21_1
L20_1[2] = L22_1
L21_1 = {}
L22_1 = "SI_EXPLORE_EVENT_RESULTDESC1_80064_6"
L23_1 = "周時雲雙手合十，靜靜閉上雙眼。\n接受所有執念，選擇不成為龍，而是作為蛇活下去的人。\n遠古時代，那位相信後代終將克服詛咒的修行者所期盼的未來，是否正是如此？\n祈禱結束後，周時雲與你一同重新展開探索。"
L21_1[1] = L22_1
L21_1[2] = L23_1
L22_1 = {}
L23_1 = "SI_EXPLORE_EVENT_SELECTION_TITLE_80064_2"
L24_1 = "拒絕協助"
L22_1[1] = L23_1
L22_1[2] = L24_1
L23_1 = {}
